def section(title, text, ident):
    return f'<section class="section container feature-split" id="{ident}"><div><p class="eyebrow">QADAMUP / {ident.upper()}</p><h2>{e(title)}</h2></div><p class="lead">{e(text)}</p></section>'

def generate(target='pages'):
    if target not in ('pages','local'):raise ValueError('Unknown build target')
    for lang,c in COPY.items():
        overdrive.enrich(lang,c)
        c['contactMode']='telegram' if target=='pages' else 'api'
        c['submit']=c['contactCTA'] if target=='pages' else {'ru':'Оставить заявку на демо','uz':'Demoga ariza qoldirish','en':'Request a demo'}[lang]
        c['dish']={'ru':'Классический бургер','en':'Classic burger','uz':'Klassik burger'}[lang]
        d=build.DATA[lang].copy()
        d.update(hero=c['hero'], intro=c['intro'], preview=c['demo'], faq=c['faq'], pricingTitle=c['pricingTitle'])
        s=build.build(lang,d,write=False)
        file=ROOT / {'ru':'index.html','uz':'uz.html','en':'en.html'}[lang]
        # Preserve static SEO and existing visual assets; replace only funnel sections.
        s=s.replace('<script src="main.js" defer></script>', '<link rel="stylesheet" href="funnel.css"><script src="funnel.js" defer></script>')
        s=re.sub(r'<link rel="preconnect".*?<link rel="stylesheet" href="styles.css">','<link rel="stylesheet" href="styles.css">',s)
        s=s.replace('href="#product">'+e(c['demo']), 'href="#demo" data-event="hero_cta_click">'+e(c['demo']),1)
        s=re.sub(r'<div class="demo-note">.*?</div>', '', s)
        s=s.replace(build.escape(d['contact'])+' <span aria-hidden="true">↗</span>',e(c['how'])+' <span aria-hidden="true">↘</span>',1)
        # Hero secondary action keeps the same appearance but moves within the funnel.
        s=s.replace('href="https://t.me/hacker_ronin" target="_blank" rel="noopener noreferrer">'+e(c['how']), 'href="#how">'+e(c['how']),1)
        problems='<div class="pain-list">'+''.join(f'<article><span>0{i+1}</span><h3>{e(x)}</h3></article>' for i,x in enumerate(c['problems']))+'</div><p class="lead">'+e(c['problemNote'])+'</p>'
        s=re.sub(r'<div class="comparison">.*?</div></section>',problems+'</section>',s,count=1)
        sliders=''
        for i,(key,lo,hi,step,val) in enumerate([('orders',5,150,5,20),('average',20000,300000,5000,80000),('commission',20,40,1,25),('share',0,100,5,30),('minutes',1,10,1,3)]):
            sliders+=f'<div class="slider-field" data-field="{key}"'+(' hidden' if key=='minutes' else '')+f'><label for="{key}">{e(c["sliders"][i])}</label><output for="{key}" id="value-{key}">{val}</output><input id="{key}" name="{key}" type="range" min="{lo}" max="{hi}" step="{step}" value="{val}"><div class="range-ends" aria-hidden="true"><span>{lo:,}</span><span>{hi:,}</span></div></div>'
        calc=f'''<section class="calculator-section" id="calculator"><div class="container"><p class="eyebrow">QADAMUP / 01</p><h2>{e(c['calcTitle'])}</h2><p class="lead">{e(c['calcText'])}</p><div class="mode-switch" role="group" aria-label="{e(c['calcTitle'])}"><button type="button" data-mode="aggregator" aria-pressed="true">{e(c['modes'][0])}</button><button type="button" data-mode="direct" aria-pressed="false">{e(c['modes'][1])}</button></div><div class="calculator-layout"><div><form id="scenario-form"><fieldset><legend class="sr-only">{e(c['calcTitle'])}</legend>{sliders}</fieldset></form><p class="fine-print" id="share-note">{e(c['shareNote'])} {e(c['commissionNote'])}</p><p id="time-note" class="fine-print" hidden>{e(c['assumption'])}</p></div><div class="calculator-result"><div id="money-results"><dl>{''.join(f'<div class="result-row"><dt>{e(label)}</dt><dd><output id="money-{i}">—</output></dd></div>' for i,label in enumerate(c['results']))}</dl><label for="scenario-plan">{e(c['planLabel'])}</label><select id="scenario-plan"><option value="fixed">{e(c['plans'][0])}</option><option value="percentage">{e(c['plans'][1])}</option></select><p class="fine-print">{e(c['planNote'])}</p><p class="fine-print">{e(c['calcNote'])}</p></div><div id="time-results" hidden><dl>{''.join(f'<div class="result-row"><dt>{e(label)}</dt><dd><output id="time-{i}">—</output></dd></div>' for i,label in enumerate(c['time']))}</dl></div><a class="btn btn-primary" data-event="calculator_cta_click" href="#demo">{e(c['how'])} ↘</a></div></div></div></section>'''
        s=re.sub(r'<section class="calculator-section".*?</section>',lambda _:calc,s,count=1,flags=re.S)
        demo=f'''<section class="dark-section" id="demo"><div class="container"><p class="eyebrow">QADAMUP / 02</p><h2>{e(c['demoTitle'])}</h2><p class="demo-disclosure">{e(c['demoNote'])}</p><div class="demo-layout"><ol class="demo-steps">{''.join(f'<li data-step="{i}">{e(x)}</li>' for i,x in enumerate(c['demoSteps']))}</ol><div class="demo-device"><div class="demo-brand">qadamup. / DEMO</div><button id="demo-open" class="btn btn-primary">{e(c['demoSteps'][0])}</button><div id="demo-menu" hidden><button id="demo-dish" class="dish"><strong>{e(c['dish'])}</strong><span>{e(c['dishNote'])}</span></button><p id="demo-selected" hidden>{e(c['selected'])}</p><button id="demo-add" class="btn btn-primary" disabled>{e(c['add'])}</button><p id="demo-cart">{e(c['empty'])}</p><button id="demo-checkout" class="btn btn-dark-outline" disabled>{e(c['checkout'])}</button></div><div id="demo-notification" hidden><h3>{e(c['notification'])}</h3><p>{e(c['dish'])} × <span id="demo-quantity"></span></p><p id="demo-status" role="status"></p><button id="demo-accept" class="btn btn-primary">{e(c['accept'])}</button><button id="demo-ready" class="btn btn-primary" hidden>{e(c['ready'])}</button></div><button id="demo-reset" class="text-link">{e(c['reset'])}</button></div></div><a class="btn btn-primary" href="#contacts">{e(c['personal'])} ↘</a></div></section>'''
        demo=demo.replace('<button id="demo-dish" class="dish">', '<button id="demo-dish" class="dish"><img src="assets/demo-burger.webp" width="640" height="360" loading="lazy" alt="'+e(c['dish'])+'">')
        s=s.replace('<section class="section container product-layout"',demo+'<section class="section container product-layout"',1)
        extras=section(c['payTitle'],c['payNote'],'payment')+section(c['reserveTitle'],c['reserveNote'],'reservations')+section(c['miniTitle'],c['miniNote'],'mini-app')
        s=s.replace('<section class="features-section"', extras+'<section class="features-section"',1)
        if os.environ.get('QADAMUP_VIDEO_READY')=='1' and all((ROOT/'assets'/name).is_file() for name in ['tour.mp4','tour-poster.webp']):
            video=f'<section class="section container" id="video"><h2>{e(c["video"])}</h2><video controls preload="none" width="1920" height="1080" poster="assets/tour-poster.webp" aria-label="{e(c["video"])}"><source src="assets/tour.mp4" type="video/mp4"></video></section>'
            s=s.replace('<section class="pricing-section"',video+'<section class="pricing-section"',1)
        pricing=f'<section class="pricing-section" id="pricing"><div class="container"><p class="eyebrow">QADAMUP / 03</p><h2>{e(c["pricingTitle"])}</h2><div class="plans">'+''.join(f'<article class="plan"><h3>{e(title)}</h3><p>{e(body)}</p><p>{e(c["included"])}</p><a class="btn btn-primary" data-event="pricing_cta_click" href="#contacts">{e(c["submit"])}</a></article>' for title,body in zip(c['plans'],c['planBodies']))+f'</div><p class="fine-print">{e(c["planNote"])}</p></div></section>'
        s=re.sub(r'<section class="pricing-section".*?</section>',lambda _:pricing,s,count=1,flags=re.S)
        lead=f'''<section class="final-section" id="contacts"><div class="container final-content"><p class="eyebrow">QADAMUP / 04</p><h2>{e(c['finalTitle'])}</h2><p class="lead">{e(c['finalText'])}</p><form id="lead-form"><label for="venue">{e(c['venue'])}</label><input id="venue" name="venue" required minlength="2" maxlength="100" autocomplete="organization"><label for="contact">{e(c['contact'])}</label><input id="contact" name="contact" required maxlength="64" autocomplete="off" aria-describedby="lead-status"><div class="honeypot" aria-hidden="true"><label>Website<input name="website" tabindex="-1" autocomplete="off"></label></div><label class="consent"><input name="consent" type="checkbox" required><span>{e(c['consent'])}</span></label><p class="fine-print">{e(c['privacy'])}</p><button class="btn btn-primary" type="submit">{e(c['submit'])}</button><p id="lead-status" role="status" aria-live="polite"></p></form><a class="text-link" href="https://t.me/hacker_ronin" target="_blank" rel="noopener noreferrer">{e(d['write'])} ↗</a><noscript><p>{e(d['nojs'])}</p></noscript></div></section>'''
        s=re.sub(r'<section class="final-section".*?</section>',lambda _:lead,s,count=1,flags=re.S)
        # Localized data drives interactions; no contacts ever enter analytics.
        browser_keys=['variantA','variantB','hours','notificationLabels','dish','cart','empty','received','accepted','complete','saving','saved','queued','error','invalid','submit','calcNote','contactMode']
        config={key:c[key] for key in browser_keys}
        config.update(locale=d['locale'],currency=d['currency'])
        s=re.sub(r'<script type="application/json" id="page-config">.*?</script>',lambda _:'<script type="application/json" id="page-config">'+json.dumps(config,ensure_ascii=False).replace('<','\\u003c')+'</script>',s)
        # Keep historical screenshot explanations but remove an outdated blanket statement.
        s=s.replace(e(d['telegramNote']),e(c['demoNote']))
        s=overdrive.present(s,lang,c)
        # Readers see either complete previous HTML or complete new HTML, never
        # the historical base template or a partially written document.
        with tempfile.NamedTemporaryFile(mode='w',encoding='utf8',newline='\n',dir=ROOT,
                                         prefix='.'+file.name+'.',suffix='.tmp',delete=False) as output:
            temporary=Path(output.name)
            output.write(s)
        try:
            temporary.replace(file)
        finally:
            temporary.unlink(missing_ok=True)
    print('FUNNEL_PAGES_BUILT')

if __name__=='__main__':
    import argparse
    parser=argparse.ArgumentParser()
    parser.add_argument('--target',choices=['pages','local'],default='pages')
    generate(parser.parse_args().target)
